export const phraseIndex = (() => {
  const indexes: Record<AppLanguage, Map<string, TranslationRow>> = {
    pl: new Map(),
    en: new Map(),
    de: new Map(),
    nl: new Map(),
    es: new Map(),
  };

  for (const item of catalog) {
    for (const lang of Object.keys(indexes) as AppLanguage[]) {
      indexes[lang].set(normalizePhrase(item[lang]), item);
    }
  }

  return indexes;
})();

export function normalizeLanguage(value: string | null | undefined): AppLanguage {
  return value === "en" || value === "de" || value === "nl" || value === "es"
    ? value
    : "pl";
}

